import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    Typography,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableRow,
    Chip,
    IconButton,
    Button,
    TextField,
    Grid,
    Card,
    CardContent,
    MenuItem,
    Select,
    FormControl,
    InputLabel,
    TablePagination,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Alert,
    Switch,
    FormControlLabel,
    Divider,
    Checkbox,
    FormGroup,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import {
    Visibility,
    PersonAdd,
    Delete,
    Flag,
    CheckCircle,
    Warning,
    Block,
    Search,
} from '@mui/icons-material';
import AdminPortalLayout from './AdminPortalLayout';
import AdminInternalNav from './AdminInternalNav';
import { isViewRoleProfile } from '../../utils/authRole';
import axios from 'axios';
import { formatFixed } from '../../utils/formatNumbers';
import { buildApiUrl } from '../../config/apiConfig';

interface MSME {
    _id: string;
    companyName: string;
    industry: string;
    status: 'pending' | 'verified' | 'flagged' | 'suspended';
    contact: {
        email: string;
        phone: string;
    };
    gstNumber: string;
    createdAt: string;
    healthScore?: number;
    healthScoreLabel?: string;
    userId: {
        email: string;
        createdAt: string;
    };
}

interface Statistics {
    msme: {
        total: number;
        verified: number;
        flagged: number;
        pending: number;
        suspended: number;
    };
}

interface SupportUser {
    _id: string;
    email: string;
    role: 'support';
    isActive: boolean;
    createdAt: string;
    lastLogin?: string;
    profile?: {
        firstName?: string;
        lastName?: string;
        phone?: string;
    };
}

interface BillingConfig {
    _id: string;
    moduleEnabled: boolean;
    informationalOnly?: boolean;
    methods: {
        upi: boolean;
        netBanking: boolean;
        cards: boolean;
    };
    updatedAt?: string;
}

interface BillingAnalyticsMethodItem {
    method: 'upi' | 'netBanking' | 'cards';
    count: number;
    totalAmount: number;
    sharePercent: number;
}

interface BillingAnalytics {
    totalTransactions: number;
    totalAmount: number;
    byMethod: BillingAnalyticsMethodItem[];
    razorpayPayments?: {
        count: number;
        totalAmount: number;
    };
}

type BillUploadFormat = 'spreadsheet' | 'pdf' | 'image';

interface PlatformFeatureConfig {
    upiDocumentPortalEnabled: boolean;
    billOcrEnabled?: boolean;
    allowedBillUploadFormats?: Record<BillUploadFormat, boolean>;
    updatedAt?: string;
}

const BILL_FORMAT_OPTIONS: Array<{ key: BillUploadFormat; label: string }> = [
    { key: 'spreadsheet', label: 'Spreadsheets (XLS, XLSX, CSV)' },
    { key: 'pdf', label: 'PDF' },
    { key: 'image', label: 'Images (JPG, PNG, WEBP, TIFF, BMP)' },
];

const describeBillUploadState = (config: PlatformFeatureConfig): string => {
    if (!config.billOcrEnabled) {
        return 'Bill reading is OFF: bill uploads are refused and no OCR credits are used.';
    }
    const formats = config.allowedBillUploadFormats || { spreadsheet: true, pdf: true, image: true };
    const accepted = BILL_FORMAT_OPTIONS.filter((option) => formats[option.key]).map((option) => option.label);
    return `Bill reading is ON, accepting: ${accepted.join(', ') || 'no formats'}.`;
};

const CLOSED_DELETE_DIALOG = {
    open: false,
    msmeId: null as string | null,
    companyName: '',
};

const AdminDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [msmes, setMsmes] = useState<MSME[]>([]);
    const [statistics, setStatistics] = useState<Statistics | null>(null);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(20);
    const [total, setTotal] = useState(0);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('');
    const [billingConfig, setBillingConfig] = useState<BillingConfig | null>(null);
    const [billingAnalytics, setBillingAnalytics] = useState<BillingAnalytics | null>(null);
    const [billingLoading, setBillingLoading] = useState(false);
    const [billingSaving, setBillingSaving] = useState(false);
    const [billingError, setBillingError] = useState<string | null>(null);
    const [billingSuccess, setBillingSuccess] = useState<string | null>(null);
    const [platformFeatures, setPlatformFeatures] = useState<PlatformFeatureConfig | null>(null);
    const [platformFeaturesLoading, setPlatformFeaturesLoading] = useState(false);
    const [platformFeaturesSaving, setPlatformFeaturesSaving] = useState(false);
    const [platformFeaturesError, setPlatformFeaturesError] = useState<string | null>(null);
    const [platformFeaturesSuccess, setPlatformFeaturesSuccess] = useState<string | null>(null);
    const [supportUsers, setSupportUsers] = useState<SupportUser[]>([]);
    const [supportUsersLoading, setSupportUsersLoading] = useState(false);
    const [creatingSupportUser, setCreatingSupportUser] = useState(false);
    const [updatingSupportAccessUserId, setUpdatingSupportAccessUserId] = useState<string | null>(null);
    const [supportUserError, setSupportUserError] = useState<string | null>(null);
    const [supportUserSuccess, setSupportUserSuccess] = useState<string | null>(null);
    const [supportUserForm, setSupportUserForm] = useState({
        firstName: '',
        lastName: '',
        phone: '',
        email: '',
        password: '',
    });
    const [deleteDialog, setDeleteDialog] = useState(CLOSED_DELETE_DIALOG);
    const [addUserDialog, setAddUserDialog] = useState({
        open: false,
        msmeId: '',
        companyName: '',
        email: '',
        password: '',
        firstName: '',
        lastName: '',
        users: [] as Array<{ id: string; email: string; isOwner?: boolean }>,
        error: null as string | null,
        saving: false,
    });
    const [error, setError] = useState<string | null>(null);
    const isViewOnlyRole = isViewRoleProfile();

    const getToken = () => localStorage.getItem('token');

    const fetchStatistics = useCallback(async () => {
        try {
            const response = await axios.get(
                buildApiUrl('/admin/msme/statistics'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setStatistics(response.data.data);
        } catch (error) {
            console.error('Error fetching statistics:', error);
        }
    }, []);

    const fetchMSMEs = useCallback(async () => {
        try {
            setLoading(true);
            const response = await axios.get(
                buildApiUrl('/admin/msme/list'),
                {
                    params: {
                        page: page + 1,
                        limit: rowsPerPage,
                        search: searchTerm || undefined,
                        status: statusFilter || undefined,
                    },
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setMsmes(response.data.data.msmes);
            setTotal(response.data.data.pagination.total);
        } catch (error: any) {
            console.error('Error fetching MSMEs:', error);
            if (error.response?.status === 403 || error.response?.status === 401) {
                navigate('/login');
            } else {
                setError('Failed to load MSME data');
            }
        } finally {
            setLoading(false);
        }
    }, [navigate, page, rowsPerPage, searchTerm, statusFilter]);

    const openAddUserDialog = async (msme: MSME) => {
        setAddUserDialog({
            open: true,
            msmeId: msme._id,
            companyName: msme.companyName,
            email: '',
            password: '',
            firstName: '',
            lastName: '',
            users: [],
            error: null,
            saving: false,
        });
        try {
            const response = await axios.get(
                buildApiUrl(`/admin/msme/${msme._id}/users`),
                { headers: { Authorization: `Bearer ${getToken()}` } }
            );
            setAddUserDialog((prev) => ({
                ...prev,
                users: response.data?.data?.users || [],
            }));
        } catch {
            setAddUserDialog((prev) => ({
                ...prev,
                error: 'Could not load the users already on this company.',
            }));
        }
    };

    const submitAddCompanyUser = async () => {
        const email = addUserDialog.email.trim();
        if (!email || !addUserDialog.password || !addUserDialog.firstName.trim()) {
            setAddUserDialog((prev) => ({
                ...prev,
                error: 'First name, email, and password are required.',
            }));
            return;
        }
        setAddUserDialog((prev) => ({ ...prev, saving: true, error: null }));
        try {
            await axios.post(
                buildApiUrl(`/admin/msme/${addUserDialog.msmeId}/users`),
                {
                    email,
                    password: addUserDialog.password,
                    firstName: addUserDialog.firstName.trim(),
                    lastName: addUserDialog.lastName.trim(),
                },
                { headers: { Authorization: `Bearer ${getToken()}` } }
            );
            setAddUserDialog((prev) => ({ ...prev, open: false, saving: false }));
            setError(null);
        } catch (submitError: any) {
            setAddUserDialog((prev) => ({
                ...prev,
                saving: false,
                error: submitError.response?.data?.message || 'Could not add this user.',
            }));
        }
    };

    const fetchPlatformFeatures = useCallback(async () => {
        try {
            setPlatformFeaturesLoading(true);
            setPlatformFeaturesError(null);
            const response = await axios.get(
                buildApiUrl('/admin/platform-features'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setPlatformFeatures(response?.data?.data?.config || null);
        } catch (fetchError: any) {
            setPlatformFeaturesError(fetchError?.response?.data?.message || 'Failed to load platform features');
        } finally {
            setPlatformFeaturesLoading(false);
        }
    }, []);

    const fetchBillingModule = useCallback(async () => {
        try {
            setBillingLoading(true);
            setBillingError(null);
            const response = await axios.get(
                buildApiUrl('/admin/billing-module'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setBillingConfig(response?.data?.data?.config || null);
            setBillingAnalytics(response?.data?.data?.analytics || null);
        } catch (fetchError: any) {
            setBillingError(fetchError?.response?.data?.message || 'Failed to load billing controls');
        } finally {
            setBillingLoading(false);
        }
    }, []);

    const fetchSupportUsers = useCallback(async () => {
        try {
            setSupportUsersLoading(true);
            const response = await axios.get(
                buildApiUrl('/admin/support-users'),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setSupportUsers(response.data?.data?.users || []);
        } catch (fetchError: any) {
            if (fetchError.response?.status !== 403 && fetchError.response?.status !== 401) {
                setSupportUserError('Failed to load customer support users');
            }
        } finally {
            setSupportUsersLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchStatistics();
        fetchMSMEs();
        if (!isViewOnlyRole) {
            fetchSupportUsers();
            fetchPlatformFeatures();
            fetchBillingModule();
        }
    }, [
        fetchBillingModule,
        fetchMSMEs,
        fetchPlatformFeatures,
        fetchStatistics,
        fetchSupportUsers,
        isViewOnlyRole,
    ]);

    const updateBillingModuleConfig = async (payload: {
        moduleEnabled?: boolean;
        informationalOnly?: boolean;
        methods?: Partial<BillingConfig['methods']>;
    }) => {
        try {
            setBillingSaving(true);
            setBillingError(null);
            setBillingSuccess(null);

            const response = await axios.put(
                buildApiUrl('/admin/billing-module'),
                payload,
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setBillingConfig(response?.data?.data?.config || null);
            setBillingAnalytics(response?.data?.data?.analytics || null);
            setBillingSuccess(response?.data?.message || 'Billing module configuration updated');
        } catch (updateError: any) {
            setBillingError(updateError?.response?.data?.message || 'Failed to update billing module');
        } finally {
            setBillingSaving(false);
        }
    };

    const handleBillingModuleToggle = (_event: React.ChangeEvent<HTMLInputElement>, checked: boolean) => {
        updateBillingModuleConfig({ moduleEnabled: checked });
    };

    const handleInformationalOnlyToggle = (_event: React.ChangeEvent<HTMLInputElement>, checked: boolean) => {
        updateBillingModuleConfig({ informationalOnly: checked });
    };

    const handleBillingMethodToggle = (method: keyof BillingConfig['methods']) => (
        _event: React.ChangeEvent<HTMLInputElement>,
        checked: boolean
    ) => {
        updateBillingModuleConfig({
            methods: {
                [method]: checked,
            },
        });
    };

    const updatePlatformFeaturesConfig = async (payload: {
        upiDocumentPortalEnabled?: boolean;
        billOcrEnabled?: boolean;
        allowedBillUploadFormats?: Partial<Record<BillUploadFormat, boolean>>;
    }) => {
        try {
            setPlatformFeaturesSaving(true);
            setPlatformFeaturesError(null);
            setPlatformFeaturesSuccess(null);

            const response = await axios.put(
                buildApiUrl('/admin/platform-features'),
                payload,
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setPlatformFeatures(response?.data?.data?.config || null);
            setPlatformFeaturesSuccess(response?.data?.message || 'Platform features updated');
        } catch (updateError: any) {
            setPlatformFeaturesError(updateError?.response?.data?.message || 'Failed to update platform features');
        } finally {
            setPlatformFeaturesSaving(false);
        }
    };

    const handleUpiDocumentPortalToggle = (_event: React.ChangeEvent<HTMLInputElement>, checked: boolean) => {
        updatePlatformFeaturesConfig({ upiDocumentPortalEnabled: checked });
    };

    const handleBillOcrToggle = (_event: React.ChangeEvent<HTMLInputElement>, checked: boolean) => {
        updatePlatformFeaturesConfig({ billOcrEnabled: checked });
    };

    const handleBillFormatToggle = (format: BillUploadFormat, checked: boolean) => {
        updatePlatformFeaturesConfig({ allowedBillUploadFormats: { [format]: checked } });
    };

    const handleSpreadsheetsOnly = () => {
        updatePlatformFeaturesConfig({ allowedBillUploadFormats: { spreadsheet: true, pdf: false, image: false } });
    };

    const handleSupportUserInputChange = (
        event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
    ) => {
        const target = event.target as HTMLInputElement & HTMLTextAreaElement & { name?: string; value: unknown };
        const { name, value } = target;
        if (!name) return;
        setSupportUserForm((prev) => ({
            ...prev,
            [name]: value,
        }));
    };

    const handleCreateSupportUser = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        setSupportUserError(null);
        setSupportUserSuccess(null);

        try {
            setCreatingSupportUser(true);
            await axios.post(
                buildApiUrl('/admin/support-users'),
                {
                    email: supportUserForm.email.trim(),
                    password: supportUserForm.password,
                    profile: {
                        firstName: supportUserForm.firstName.trim(),
                        lastName: supportUserForm.lastName.trim(),
                        phone: supportUserForm.phone.trim(),
                    },
                },
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            setSupportUserSuccess('Customer support user created successfully');
            setSupportUserForm({
                firstName: '',
                lastName: '',
                phone: '',
                email: '',
                password: '',
            });
            fetchSupportUsers();
        } catch (createError: any) {
            setSupportUserError(createError?.response?.data?.message || 'Failed to create support user');
        } finally {
            setCreatingSupportUser(false);
        }
    };

    const handleSupportUserAccessChange = async (userId: string, isActive: boolean) => {
        setSupportUserError(null);
        setSupportUserSuccess(null);

        try {
            setUpdatingSupportAccessUserId(userId);
            const response = await axios.patch(
                buildApiUrl(`/admin/support-users/${userId}/access`),
                { isActive },
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );

            const updatedUser = response?.data?.data?.user;
            if (updatedUser?._id) {
                setSupportUsers((prevUsers) =>
                    prevUsers.map((user) => (user._id === updatedUser._id ? updatedUser : user))
                );
            } else {
                fetchSupportUsers();
            }

            setSupportUserSuccess(
                response?.data?.message ||
                    (isActive ? 'Support user access enabled successfully' : 'Support user access removed successfully')
            );
        } catch (updateError: any) {
            setSupportUserError(updateError?.response?.data?.message || 'Failed to update support user access');
        } finally {
            setUpdatingSupportAccessUserId(null);
        }
    };

    const handleSearch = () => {
        setPage(0);
        fetchMSMEs();
    };

    const handleDelete = async () => {
        if (!deleteDialog.msmeId) return;

        try {
            await axios.delete(
                buildApiUrl(`/admin/msme/${deleteDialog.msmeId}?deleteUser=true`),
                {
                    headers: { Authorization: `Bearer ${getToken()}` },
                }
            );
            setDeleteDialog(CLOSED_DELETE_DIALOG);
            fetchMSMEs();
            fetchStatistics();
        } catch (error) {
            console.error('Error deleting MSME:', error);
            setError('Failed to delete MSME');
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'verified':
                return 'success';
            case 'flagged':
                return 'warning';
            case 'suspended':
                return 'error';
            default:
                return 'default';
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'verified':
                return <CheckCircle />;
            case 'flagged':
                return <Warning />;
            case 'suspended':
                return <Block />;
            default:
                return <Flag />;
        }
    };

    const formatMethodLabel = (value: BillingAnalyticsMethodItem['method']) => {
        switch (value) {
            case 'netBanking':
                return 'Netbanking';
            case 'cards':
                return 'Cards';
            default:
                return 'UPI';
        }
    };

    const formatInrCurrency = (value: number) =>
        new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency: 'INR',
            maximumFractionDigits: 2,
        }).format(value || 0);

    return (
        <AdminPortalLayout
            title={isViewOnlyRole ? 'MSME registry' : 'Admin dashboard'}
            subtitle="Search, review, and manage registered MSME accounts."
        >
                {!isViewOnlyRole ? (
                <Box sx={{ mb: 2, display: 'flex', justifyContent: 'flex-end', gap: 1, flexWrap: 'wrap' }}>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={() => navigate('/admin/emission-factors')}
                    >
                        Factor review
                    </Button>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={() => navigate('/admin/system-health')}
                    >
                        System health
                    </Button>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={() => navigate('/admin/ocr-automation')}
                    >
                        OCR automation
                    </Button>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={() => navigate('/admin/integrations')}
                    >
                        Integration APIs
                    </Button>
                </Box>
                ) : null}
                <AdminInternalNav />
                {error && (
                    <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
                        {error}
                    </Alert>
                )}

                {/* Statistics Cards */}
                {statistics && (
                    <Grid container spacing={3} sx={{ mb: 4 }}>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Total MSMEs
                                    </Typography>
                                    <Typography variant="h4">{statistics.msme.total}</Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'success.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Verified
                                    </Typography>
                                    <Typography variant="h4" color="success.main">
                                        {statistics.msme.verified}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'warning.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Flagged
                                    </Typography>
                                    <Typography variant="h4" color="warning.main">
                                        {statistics.msme.flagged}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'info.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Pending
                                    </Typography>
                                    <Typography variant="h4" color="info.main">
                                        {statistics.msme.pending}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                        <Grid item xs={12} sm={6} md={2.4}>
                            <Card sx={{ borderLeft: 4, borderColor: 'error.main' }}>
                                <CardContent>
                                    <Typography color="text.secondary" gutterBottom variant="body2">
                                        Suspended
                                    </Typography>
                                    <Typography variant="h4" color="error.main">
                                        {statistics.msme.suspended}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                    </Grid>
                )}

                {/* Filters */}
                <Paper sx={{ p: 2, mb: 3 }}>
                    <Grid container spacing={2} alignItems="center">
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                size="small"
                                placeholder="Search by company name, email, GST, PAN..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') handleSearch();
                                }}
                                InputProps={{
                                    endAdornment: (
                                        <IconButton onClick={handleSearch} size="small" aria-label="Search MSMEs">
                                            <Search />
                                        </IconButton>
                                    ),
                                }}
                            />
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <FormControl fullWidth size="small">
                                <InputLabel>Status</InputLabel>
                                <Select
                                    value={statusFilter}
                                    label="Status"
                                    onChange={(e) => {
                                        setStatusFilter(e.target.value);
                                        setPage(0);
                                    }}
                                >
                                    <MenuItem value="">All</MenuItem>
                                    <MenuItem value="pending">Pending</MenuItem>
                                    <MenuItem value="verified">Verified</MenuItem>
                                    <MenuItem value="flagged">Flagged</MenuItem>
                                    <MenuItem value="suspended">Suspended</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12} md={3}>
                            <Button
                                fullWidth
                                variant="outlined"
                                onClick={() => {
                                    setSearchTerm('');
                                    setStatusFilter('');
                                    setPage(0);
                                }}
                            >
                                Clear Filters
                            </Button>
                        </Grid>
                    </Grid>
                </Paper>

                {!isViewOnlyRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                            Customer Support User Provisioning
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                            Create customer support accounts with visibility into MSME user status, usage,
                            account issues, and resolution tracking.
                        </Typography>

                        {supportUserError && (
                            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setSupportUserError(null)}>
                                {supportUserError}
                            </Alert>
                        )}
                        {supportUserSuccess && (
                            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSupportUserSuccess(null)}>
                                {supportUserSuccess}
                            </Alert>
                        )}

                        <Box component="form" onSubmit={handleCreateSupportUser} sx={{ mb: 3 }}>
                            <Grid container spacing={2}>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="First Name"
                                        name="firstName"
                                        value={supportUserForm.firstName}
                                        onChange={handleSupportUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Last Name"
                                        name="lastName"
                                        value={supportUserForm.lastName}
                                        onChange={handleSupportUserInputChange}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Phone"
                                        name="phone"
                                        value={supportUserForm.phone}
                                        onChange={handleSupportUserInputChange}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        type="email"
                                        label="Email"
                                        name="email"
                                        value={supportUserForm.email}
                                        onChange={handleSupportUserInputChange}
                                        required
                                    />
                                </Grid>
                                <Grid item xs={12} md={3}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        type="password"
                                        label="Temporary Password"
                                        name="password"
                                        value={supportUserForm.password}
                                        onChange={handleSupportUserInputChange}
                                        required
                                        inputProps={{ minLength: 6 }}
                                    />
                                </Grid>
                                <Grid item xs={12} md={3} sx={{ display: 'flex', alignItems: 'center' }}>
                                    <Button
                                        type="submit"
                                        variant="contained"
                                        fullWidth
                                        disabled={creatingSupportUser}
                                    >
                                        {creatingSupportUser ? 'Adding User...' : 'Add Support User'}
                                    </Button>
                                </Grid>
                            </Grid>
                        </Box>

                        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                            Provisioned Support Users
                        </Typography>
                        <ScrollableTableContainer component={Paper} variant="outlined">
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell><strong>Name</strong></TableCell>
                                        <TableCell><strong>Email</strong></TableCell>
                                        <TableCell><strong>Last Login</strong></TableCell>
                                        <TableCell><strong>Status</strong></TableCell>
                                        <TableCell><strong>Access Control</strong></TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {supportUsersLoading ? (
                                        <TableRow>
                                            <TableCell colSpan={5} align="center">Loading support users...</TableCell>
                                        </TableRow>
                                    ) : supportUsers.length === 0 ? (
                                        <TableRow>
                                            <TableCell colSpan={5} align="center">No customer support users found</TableCell>
                                        </TableRow>
                                    ) : (
                                        supportUsers.map((user) => (
                                            <TableRow key={user._id} hover>
                                                <TableCell>
                                                    {[user.profile?.firstName, user.profile?.lastName]
                                                        .filter(Boolean)
                                                        .join(' ') || 'N/A'}
                                                </TableCell>
                                                <TableCell>{user.email}</TableCell>
                                                <TableCell>
                                                    {user.lastLogin
                                                        ? new Date(user.lastLogin).toLocaleDateString()
                                                        : 'Never'}
                                                </TableCell>
                                                <TableCell>
                                                    <Chip
                                                        label={user.isActive ? 'Active' : 'Inactive'}
                                                        color={user.isActive ? 'success' : 'default'}
                                                        size="small"
                                                    />
                                                </TableCell>
                                                <TableCell>
                                                    <Button
                                                        size="small"
                                                        variant={user.isActive ? 'outlined' : 'contained'}
                                                        color={user.isActive ? 'error' : 'success'}
                                                        disabled={updatingSupportAccessUserId === user._id}
                                                        onClick={() =>
                                                            handleSupportUserAccessChange(user._id, !user.isActive)
                                                        }
                                                    >
                                                        {updatingSupportAccessUserId === user._id
                                                            ? 'Updating...'
                                                            : user.isActive
                                                                ? 'Remove Access'
                                                                : 'Allow User'}
                                                    </Button>
                                                </TableCell>
                                            </TableRow>
                                        ))
                                    )}
                                </TableBody>
                            </Table>
                        </ScrollableTableContainer>
                    </Paper>
                )}

                {!isViewOnlyRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                            Platform Features
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            Control optional MSME-facing modules. UPI document portal is hidden by default.
                        </Typography>

                        {platformFeaturesError && (
                            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setPlatformFeaturesError(null)}>
                                {platformFeaturesError}
                            </Alert>
                        )}
                        {platformFeaturesSuccess && (
                            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setPlatformFeaturesSuccess(null)}>
                                {platformFeaturesSuccess}
                            </Alert>
                        )}

                        {platformFeaturesLoading ? (
                            <Typography variant="body2" color="text.secondary">
                                Loading platform features...
                            </Typography>
                        ) : platformFeatures ? (
                            <Paper variant="outlined" sx={{ p: 2, maxWidth: 480 }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                    UPI Document Portal
                                </Typography>
                                <FormControlLabel
                                    control={(
                                        <Switch
                                            checked={platformFeatures.upiDocumentPortalEnabled === true}
                                            onChange={handleUpiDocumentPortalToggle}
                                            disabled={platformFeaturesSaving}
                                        />
                                    )}
                                    label={platformFeatures.upiDocumentPortalEnabled ? 'Visible on Upload documents' : 'Hidden'}
                                />
                                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                                    When enabled, MSMEs see the UPI pay-and-upload panel on the document upload page.
                                </Typography>
                            </Paper>
                        ) : null}

                        {!platformFeaturesLoading && platformFeatures ? (
                            <Paper variant="outlined" sx={{ p: 2, maxWidth: 480, mt: 2 }}>
                                <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                    Bill reading (OCR)
                                </Typography>
                                <FormControlLabel
                                    control={(
                                        <Switch
                                            checked={platformFeatures.billOcrEnabled === true}
                                            onChange={handleBillOcrToggle}
                                            disabled={platformFeaturesSaving}
                                            inputProps={{ 'aria-label': 'Bill reading (OCR)' }}
                                        />
                                    )}
                                    label={platformFeatures.billOcrEnabled ? 'On: bills are uploaded and read' : 'Off: bill uploads are refused'}
                                />
                                <Typography variant="body2" sx={{ fontWeight: 600, mt: 2 }}>
                                    Accepted bill formats
                                </Typography>
                                <FormGroup>
                                    {BILL_FORMAT_OPTIONS.map((option) => {
                                        const formats = platformFeatures.allowedBillUploadFormats
                                            || { spreadsheet: true, pdf: true, image: true };
                                        const checked = formats[option.key] !== false;
                                        // At least one format stays allowed; switch bill reading off instead.
                                        const isLastAllowed = checked
                                            && BILL_FORMAT_OPTIONS.filter((o) => formats[o.key] !== false).length === 1;
                                        return (
                                            <FormControlLabel
                                                key={option.key}
                                                control={(
                                                    <Checkbox
                                                        checked={checked}
                                                        onChange={(_event, value) => handleBillFormatToggle(option.key, value)}
                                                        disabled={platformFeaturesSaving || !platformFeatures.billOcrEnabled || isLastAllowed}
                                                    />
                                                )}
                                                label={option.label}
                                            />
                                        );
                                    })}
                                </FormGroup>
                                <Button
                                    size="small"
                                    variant="outlined"
                                    sx={{ mt: 1 }}
                                    onClick={handleSpreadsheetsOnly}
                                    disabled={platformFeaturesSaving || !platformFeatures.billOcrEnabled}
                                >
                                    Spreadsheets only
                                </Button>
                                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                                    {describeBillUploadState(platformFeatures)} Changes reach MSME upload screens within a minute.
                                </Typography>
                            </Paper>
                        ) : !platformFeaturesLoading ? (
                            <Typography variant="body2" color="text.secondary">
                                Platform feature configuration is currently unavailable.
                            </Typography>
                        ) : null}
                    </Paper>
                )}

                {!isViewOnlyRole && (
                    <Paper sx={{ p: 3, mb: 3 }}>
                        <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                            Billing Module Control
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            Configure billing module availability, control payment methods, and monitor billing analytics.
                        </Typography>

                        {billingError && (
                            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setBillingError(null)}>
                                {billingError}
                            </Alert>
                        )}
                        {billingSuccess && (
                            <Alert severity="success" sx={{ mb: 2 }} onClose={() => setBillingSuccess(null)}>
                                {billingSuccess}
                            </Alert>
                        )}

                        {billingLoading ? (
                            <Typography variant="body2" color="text.secondary">
                                Loading billing controls...
                            </Typography>
                        ) : billingConfig ? (
                            <>
                                <Grid container spacing={2} sx={{ mb: 2 }}>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                                Module Status
                                            </Typography>
                                            <FormControlLabel
                                                control={(
                                                    <Switch
                                                        checked={billingConfig.moduleEnabled}
                                                        onChange={handleBillingModuleToggle}
                                                        disabled={billingSaving}
                                                    />
                                                )}
                                                label={billingConfig.moduleEnabled ? 'Enabled' : 'Disabled'}
                                            />
                                            <Chip
                                                label={billingConfig.moduleEnabled ? 'Live for configured methods' : 'Module disabled'}
                                                color={billingConfig.moduleEnabled ? 'success' : 'default'}
                                                size="small"
                                                sx={{ mt: 1 }}
                                            />
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                                Access Policy
                                            </Typography>
                                            <FormControlLabel
                                                control={(
                                                    <Switch
                                                        checked={billingConfig.informationalOnly !== false}
                                                        onChange={handleInformationalOnlyToggle}
                                                        disabled={billingSaving}
                                                    />
                                                )}
                                                label={billingConfig.informationalOnly !== false ? 'Informational only' : 'Payments enforce entitlements'}
                                            />
                                            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                                                Informational mode records MSME payments without restricting product access.
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={4}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
                                                Payment Methods
                                            </Typography>
                                            <Grid container spacing={1}>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.upi || false}
                                                                onChange={handleBillingMethodToggle('upi')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="UPI Payment"
                                                    />
                                                </Grid>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.netBanking || false}
                                                                onChange={handleBillingMethodToggle('netBanking')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="Netbanking"
                                                    />
                                                </Grid>
                                                <Grid item xs={12} sm={4}>
                                                    <FormControlLabel
                                                        control={(
                                                            <Switch
                                                                checked={billingConfig.methods?.cards || false}
                                                                onChange={handleBillingMethodToggle('cards')}
                                                                disabled={billingSaving}
                                                            />
                                                        )}
                                                        label="Cards Payment"
                                                    />
                                                </Grid>
                                            </Grid>
                                        </Paper>
                                    </Grid>
                                </Grid>

                                <Divider sx={{ my: 2 }} />

                                <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                                    Billing Analytics
                                </Typography>
                                <Grid container spacing={2} sx={{ mb: 2 }}>
                                    <Grid item xs={12} md={3}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Razorpay Payments
                                            </Typography>
                                            <Typography variant="h6">
                                                {billingAnalytics?.razorpayPayments?.count ?? 0}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={3}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Razorpay Amount
                                            </Typography>
                                            <Typography variant="h6">
                                                {formatInrCurrency(billingAnalytics?.razorpayPayments?.totalAmount ?? 0)}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={3}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Accounting-linked Transactions
                                            </Typography>
                                            <Typography variant="h6">
                                                {billingAnalytics?.totalTransactions ?? 0}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={3}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Accounting-linked Amount
                                            </Typography>
                                            <Typography variant="h6">
                                                {formatInrCurrency(billingAnalytics?.totalAmount ?? 0)}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                    <Grid item xs={12} md={3}>
                                        <Paper variant="outlined" sx={{ p: 2 }}>
                                            <Typography variant="body2" color="text.secondary">
                                                Last Config Update
                                            </Typography>
                                            <Typography variant="h6">
                                                {billingConfig.updatedAt
                                                    ? new Date(billingConfig.updatedAt).toLocaleDateString()
                                                    : 'N/A'}
                                            </Typography>
                                        </Paper>
                                    </Grid>
                                </Grid>

                                <ScrollableTableContainer component={Paper} variant="outlined">
                                    <Table size="small">
                                        <TableHead>
                                            <TableRow>
                                                <TableCell><strong>Method</strong></TableCell>
                                                <TableCell><strong>Transactions</strong></TableCell>
                                                <TableCell><strong>Total Amount</strong></TableCell>
                                                <TableCell><strong>Share</strong></TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            {(billingAnalytics?.byMethod || []).map((methodItem) => (
                                                <TableRow key={methodItem.method}>
                                                    <TableCell>{formatMethodLabel(methodItem.method)}</TableCell>
                                                    <TableCell>{methodItem.count}</TableCell>
                                                    <TableCell>{formatInrCurrency(methodItem.totalAmount)}</TableCell>
                                                    <TableCell>{formatFixed(methodItem.sharePercent, 2)}%</TableCell>
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                    </Table>
                                </ScrollableTableContainer>
                            </>
                        ) : (
                            <Typography variant="body2" color="text.secondary">
                                Billing module configuration is currently unavailable.
                            </Typography>
                        )}
                    </Paper>
                )}

                {/* MSME Table */}
                <ScrollableTableContainer component={Paper} sx={{ border: 1, borderColor: 'divider', borderRadius: 2 }}>
                    <Table aria-label="MSME registry table" stickyHeader>
                        <TableHead>
                            <TableRow>
                                <TableCell><strong>Company Name</strong></TableCell>
                                <TableCell><strong>Industry</strong></TableCell>
                                <TableCell><strong>Email</strong></TableCell>
                                <TableCell><strong>Status</strong></TableCell>
                                <TableCell><strong>Health</strong></TableCell>
                                <TableCell><strong>Registered</strong></TableCell>
                                <TableCell align="center"><strong>{isViewOnlyRole ? 'View' : 'Actions'}</strong></TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={7} align="center" sx={{ py: 4 }}>
                                        <Typography variant="body2" color="text.secondary">
                                            Loading MSME registry records...
                                        </Typography>
                                    </TableCell>
                                </TableRow>
                            ) : msmes.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={7} align="center" sx={{ py: 4 }}>
                                        <Typography variant="body2" color="text.secondary">
                                            No MSMEs matched the current filters.
                                        </Typography>
                                        <Button
                                            sx={{ mt: 1.5 }}
                                            size="small"
                                            onClick={() => {
                                                setSearchTerm('');
                                                setStatusFilter('');
                                                setPage(0);
                                            }}
                                        >
                                            Reset filters
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ) : (
                                msmes.map((msme) => (
                                    <TableRow
                                        key={msme._id}
                                        hover
                                        sx={{
                                            '&:nth-of-type(odd)': { bgcolor: 'action.hover' },
                                            '&:hover': { bgcolor: 'action.selected' },
                                        }}
                                    >
                                        <TableCell>{msme.companyName}</TableCell>
                                        <TableCell>{msme.industry}</TableCell>
                                        <TableCell>{msme.contact.email}</TableCell>
                                        <TableCell>
                                            <Chip
                                                icon={getStatusIcon(msme.status || 'pending')}
                                                label={msme.status ? msme.status.charAt(0).toUpperCase() + msme.status.slice(1) : 'Pending'}
                                                color={getStatusColor(msme.status || 'pending') as any}
                                                size="small"
                                            />
                                        </TableCell>
                                        <TableCell>
                                            <Chip
                                                size="small"
                                                variant="outlined"
                                                label={`${msme.healthScore ?? 0} · ${msme.healthScoreLabel || 'New'}`}
                                                color={(msme.healthScore ?? 0) >= 80 ? 'success' : (msme.healthScore ?? 0) >= 50 ? 'info' : 'default'}
                                            />
                                        </TableCell>
                                        <TableCell>
                                            {new Date(msme.createdAt).toLocaleDateString()}
                                        </TableCell>
                                        <TableCell align="center">
                                            <IconButton
                                                size="small"
                                                onClick={() => navigate(`/admin/msme/${msme._id}`)}
                                                title="View Details"
                                                aria-label={`View ${msme.companyName} details`}
                                            >
                                                <Visibility />
                                            </IconButton>
                                            {!isViewOnlyRole && (
                                                <IconButton
                                                    size="small"
                                                    color="primary"
                                                    onClick={() => openAddUserDialog(msme)}
                                                    title="Add user"
                                                    aria-label={`Add user to ${msme.companyName}`}
                                                >
                                                    <PersonAdd />
                                                </IconButton>
                                            )}
                                            {!isViewOnlyRole && (
                                                <IconButton
                                                    size="small"
                                                    color="error"
                                                    onClick={() =>
                                                        setDeleteDialog({
                                                            open: true,
                                                            msmeId: msme._id,
                                                            companyName: msme.companyName,
                                                        })
                                                    }
                                                    title="Delete MSME"
                                                    aria-label={`Delete ${msme.companyName}`}
                                                >
                                                    <Delete />
                                                </IconButton>
                                            )}
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                    <TablePagination
                        rowsPerPageOptions={[10, 20, 50]}
                        component="div"
                        count={total}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={(_, newPage) => setPage(newPage)}
                        onRowsPerPageChange={(e) => {
                            setRowsPerPage(parseInt(e.target.value, 10));
                            setPage(0);
                        }}
                    />
                </ScrollableTableContainer>

                {!isViewOnlyRole && (
                    <Dialog
                        open={addUserDialog.open}
                        onClose={() => setAddUserDialog((prev) => ({ ...prev, open: false, error: null }))}
                        fullWidth
                        maxWidth="sm"
                    >
                        <DialogTitle>Add user to {addUserDialog.companyName || 'company'}</DialogTitle>
                        <DialogContent>
                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Email is the login credential. This user joins the existing company profile and does not create another one.
                            </Typography>
                            {addUserDialog.error && (
                                <Alert severity="error" sx={{ mb: 2 }}>{addUserDialog.error}</Alert>
                            )}
                            {addUserDialog.users.length > 0 && (
                                <Typography variant="body2" sx={{ mb: 2 }}>
                                    Current logins: {addUserDialog.users.map((user) => user.email).join(', ')}
                                </Typography>
                            )}
                            <TextField
                                margin="dense"
                                label="First name"
                                fullWidth
                                value={addUserDialog.firstName}
                                onChange={(event) => setAddUserDialog((prev) => ({ ...prev, firstName: event.target.value }))}
                            />
                            <TextField
                                margin="dense"
                                label="Last name"
                                fullWidth
                                value={addUserDialog.lastName}
                                onChange={(event) => setAddUserDialog((prev) => ({ ...prev, lastName: event.target.value }))}
                            />
                            <TextField
                                margin="dense"
                                label="Email"
                                type="email"
                                fullWidth
                                value={addUserDialog.email}
                                onChange={(event) => setAddUserDialog((prev) => ({ ...prev, email: event.target.value }))}
                            />
                            <TextField
                                margin="dense"
                                label="Password"
                                type="password"
                                fullWidth
                                value={addUserDialog.password}
                                onChange={(event) => setAddUserDialog((prev) => ({ ...prev, password: event.target.value }))}
                            />
                        </DialogContent>
                        <DialogActions>
                            <Button onClick={() => setAddUserDialog((prev) => ({ ...prev, open: false }))}>Cancel</Button>
                            <Button variant="contained" disabled={addUserDialog.saving} onClick={submitAddCompanyUser}>
                                {addUserDialog.saving ? 'Adding...' : 'Add user'}
                            </Button>
                        </DialogActions>
                    </Dialog>
                )}

                {/* Delete Confirmation Dialog */}
                {!isViewOnlyRole && (
                    <Dialog open={deleteDialog.open} onClose={() => setDeleteDialog(CLOSED_DELETE_DIALOG)}>
                        <DialogTitle>Confirm Deletion</DialogTitle>
                        <DialogContent>
                            <Alert severity="warning" sx={{ mt: 1 }}>
                                This action is permanent and will remove the MSME profile and linked user account.
                            </Alert>
                            <Typography sx={{ mt: 2 }}>
                                Company selected: <strong>{deleteDialog.companyName || 'N/A'}</strong>
                            </Typography>
                        </DialogContent>
                        <DialogActions>
                            <Button onClick={() => setDeleteDialog(CLOSED_DELETE_DIALOG)}>
                                Cancel
                            </Button>
                            <Button onClick={handleDelete} color="error" variant="contained">
                                Delete
                            </Button>
                        </DialogActions>
                    </Dialog>
                )}
        </AdminPortalLayout>
    );
};

export default AdminDashboard;
